// and every whole-percent discount.

function refundAsCoded(subtotalCents: number, discountPercent: number): number {
  return Math.round(subtotalCents * (1 - discountPercent / 100));
}

function halfUpInteger(subtotalCents: number, discountPercent: number): number {
  const discounted = subtotalCents * (100 - discountPercent);
  return Math.floor((discounted + 50) / 100);
}

const mismatches: { subtotalCents: number; discountPercent: number; coded: number; halfUp: number }[] = [];
let ties = 0;
for (let subtotal = 1; subtotal <= 10_000; subtotal++) {
  for (let d = 0; d <= 100; d++) {
    const isTie = (subtotal * (100 - d)) % 100 === 50;
    if (isTie) ties++;
    const coded = refundAsCoded(subtotal, d);
    const halfUp = halfUpInteger(subtotal, d);
    if (coded !== halfUp) mismatches.push({ subtotalCents: subtotal, discountPercent: d, coded, halfUp });
  }
}

console.log(`exact half-cent ties checked: ${ties}`);
console.log(`mismatches: ${mismatches.length}`);
console.log("first 15:");
for (const m of mismatches.slice(0, 15)) console.log(JSON.stringify(m));

console.log("\nthe doc's example, 8.50 at 33% off:");
console.log(`  float product  = ${850 * (1 - 33 / 100)}`);
console.log(`  as coded       = ${refundAsCoded(850, 33)}`);
console.log(`  half up (int)  = ${halfUpInteger(850, 33)}`);

